/* Wedding website template — generated by builder/build.py. Settings are read from data-* attributes. */
document.addEventListener('DOMContentLoaded', () => {
  /* Mobile nav */
  const toggle = document.getElementById('nav-toggle');
  const nav = document.getElementById('main-nav');
  if (toggle && nav) {
    toggle.addEventListener('click', () => {
      const open = nav.classList.toggle('open');
      toggle.classList.toggle('open', open);
      toggle.setAttribute('aria-expanded', String(open));
    });
  }

  /* Highlight current page */
  const current = location.pathname.split('/').pop() || 'index.html';
  document.querySelectorAll('.main-nav a').forEach((a) => {
    if (a.getAttribute('href') === current) a.classList.add('active');
  });

  /* Countdown */
  const cd = document.getElementById('countdown');
  if (cd) {
    const target = new Date(cd.dataset.target).getTime();
    const set = (sel, v) => { const el = cd.querySelector(sel); if (el) el.textContent = v; };
    const tick = () => {
      const diff = Math.max(0, target - Date.now());
      set('[data-days]', String(Math.floor(diff / 86400000)));
      set('[data-hours]', String(Math.floor(diff / 3600000) % 24).padStart(2, '0'));
      set('[data-minutes]', String(Math.floor(diff / 60000) % 60).padStart(2, '0'));
      set('[data-seconds]', String(Math.floor(diff / 1000) % 60).padStart(2, '0'));
    };
    tick();
    setInterval(tick, 1000);
  }

  /* FAQ accordion */
  document.querySelectorAll('.faq-question').forEach((btn) => {
    btn.addEventListener('click', () => {
      const item = btn.closest('.faq-item');
      const open = item.classList.toggle('open');
      btn.setAttribute('aria-expanded', String(open));
    });
  });

  /* Gallery lock — answers are stored as SHA-256 hashes, not plain text */
  const gateForm = document.getElementById('gallery-gate-form');
  if (gateForm) {
    const gate = document.getElementById('gallery-gate');
    const content = document.getElementById('gallery-content');
    const error = document.getElementById('gate-error');
    const key = 'galleryUnlocked:' + location.host;
    const unlock = () => { gate.style.display = 'none'; content.style.display = 'block'; };
    try { if (localStorage.getItem(key) === 'true') unlock(); } catch (e) { /* storage blocked */ }

    const sha = async (text) => {
      const buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text));
      return [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, '0')).join('');
    };
    const norm = (s) => s.trim().toLowerCase().replace(/\s+/g, ' ');

    gateForm.addEventListener('submit', async (e) => {
      e.preventDefault();
      const inputs = [...gateForm.querySelectorAll('[data-hash]')];
      const results = await Promise.all(inputs.map(async (inp) => (await sha(norm(inp.value))) === inp.dataset.hash));
      if (results.every(Boolean)) {
        error.style.display = 'none';
        try { localStorage.setItem(key, 'true'); } catch (err) { /* ignore */ }
        unlock();
      } else {
        error.style.display = 'block';
      }
    });
  }

  /* On-site RSVP form → emailed to the couple via FormSubmit, WhatsApp as fallback */
  const rsvp = document.getElementById('rsvp-form');
  if (rsvp) {
    const status = document.getElementById('rsvp-status');
    rsvp.addEventListener('submit', async (e) => {
      e.preventDefault();
      const data = Object.fromEntries(new FormData(rsvp).entries());
      const lines = Object.entries(data).filter(([k, v]) => !k.startsWith('_') && v).map(([k, v]) => `${k}: ${v}`);
      status.className = 'rsvp-status';
      status.textContent = rsvp.dataset.sending;
      try {
        if (!rsvp.dataset.endpoint) throw new Error('no endpoint');
        const res = await fetch(rsvp.dataset.endpoint, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
          body: JSON.stringify(data)
        });
        const out = await res.json().catch(() => ({}));
        // FormSubmit replies 200 with success:"false" until the form is activated
        if (!res.ok || String(out.success) === 'false') throw new Error(out.message || res.statusText);
        rsvp.reset();
        status.className = 'rsvp-status ok';
        status.textContent = rsvp.dataset.thanks;
      } catch (err) {
        if (rsvp.dataset.whatsapp) {
          window.open(`https://wa.me/${rsvp.dataset.whatsapp}?text=${encodeURIComponent('RSVP\n' + lines.join('\n'))}`, '_blank');
          status.className = 'rsvp-status ok';
          status.textContent = rsvp.dataset.fallback;
        } else {
          status.className = 'rsvp-status err';
          status.textContent = rsvp.dataset.error;
        }
      }
    });
  }
});
